import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='RENTRI'
E(C,'M1-Z1','Chi deve iscriversi dal 2026: la riforma dell’art. 188-bis',[CL("Iscrizione al RENTRI: sì o no?","Seleziona un’impresa, poi la risposta.",["Obbligata all’iscrizione","Non obbligata"],[
 ["Officina meccanica con 4 dipendenti che produce oli esausti e filtri",0,"Produce rifiuti pericolosi: è obbligata, a prescindere dal numero di dipendenti."],
 ["Studio di architettura che produce solo carta e toner non pericolosi",1,"Rifiuti non pericolosi da attività di servizio: non rientra nell’art. 189, comma 3."],
 ["Falegnameria artigiana con 8 dipendenti che produce solo segatura e trucioli non pericolosi",0,"Rifiuti non pericolosi da lavorazione artigianale: rientra nell’art. 189, comma 3."],
 ["Impianto autorizzato al recupero di rifiuti inerti",0,"Chi effettua il trattamento dei rifiuti è obbligato."],
 ["Negozio di abbigliamento che produce imballaggi in cartone",1,"Rifiuti non pericolosi da attività commerciale: non è obbligato."],
 ["Impresa che trasporta rifiuti pericolosi per conto terzi",0,"Raccolta e trasporto professionale di rifiuti pericolosi: obbligata."],
 ["Ufficio amministrativo che produce solo rifiuti urbani",1,"Non è tra i soggetti obbligati."],
 ["Carrozzeria con 15 dipendenti che produce vernici di scarto",0,"Produttore di rifiuti pericolosi: obbligata."]],
 "Otto imprese. Per ciascuna stabilisci se deve iscriversi al RENTRI secondo il nuovo comma 3-bis dell’articolo centottantotto bis.","Art. 188-bis, c. 3-bis, D.lgs. 152/2006")])
E(C,'M1-Z2','Il deposito temporaneo prima della raccolta',[SC("I fusti nel retro del capannone","Un’officina tiene nel retro del capannone fusti di oli esausti e contenitori di filtri. L’ultimo ritiro risale a cinque mesi fa; il volume complessivo è di circa 4 metri cubi.",[
 ("Il deposito è ancora regolare?",[["No: con il criterio temporale serve un avvio almeno trimestrale; con il criterio quantitativo si può arrivare fino a un anno se non si superano 30 m³, di cui 10 di pericolosi",True,"Corretto: conta il criterio scelto e documentato dall’impresa."],["Sì, sempre: il deposito temporaneo non ha limiti finché i rifiuti restano in azienda",False,"Il deposito ha limiti di tempo e di quantità: oltre diventa stoccaggio non autorizzato."],["No, perché i rifiuti pericolosi vanno ritirati ogni mese",False,"Non esiste un obbligo mensile."]]),
 ("I fusti sono all’aperto, senza bacino di contenimento e senza etichetta. Che cosa fai?",[["Nulla, il deposito è temporaneo",False,"Le norme tecniche e l’etichettatura dei rifiuti pericolosi valgono anche nel deposito temporaneo."],["Sposti i fusti su un bacino di contenimento, al coperto, li etichetti e separi i rifiuti per categorie omogenee",True,"Corretto: sono le condizioni dell’art. 185-bis."],["Travasi tutto in un unico contenitore per semplificare",False,"La miscelazione di rifiuti pericolosi è vietata salvo autorizzazione."]]),
 ("Come dimostri il rispetto dei limiti a un controllo?",[["Con le annotazioni del registro di carico e scarico e i formulari dei ritiri",True,"Corretto: il registro documenta date e quantità di produzione e di avvio."],["Con una dichiarazione verbale del titolare",False,"Serve una prova documentale."],["Con le fatture del carburante",False,"Non riguardano i rifiuti."]])],
 "Scegliere il criterio, rispettare le condizioni tecniche e documentare tutto nel registro: così il deposito temporaneo resta tale e non diventa stoccaggio non autorizzato.","Un deposito di rifiuti pericolosi da verificare. Decidi se è regolare e come metterlo a posto.","Art. 185-bis D.lgs. 152/2006")])
E(C,'M1-Z3','Le quindici caratteristiche di pericolo',[LB("Laboratorio · I rifiuti dell’officina meccanica","Un’officina di riparazione di autoveicoli con 6 dipendenti ti chiede di impostare la gestione dei rifiuti.",[
  ["Attività","Manutenzione e riparazione di autoveicoli"],["Dipendenti","6"],["Rifiuti prodotti","oli motore esausti, filtri dell’olio, stracci sporchi d’olio, batterie al piombo, imballaggi in materiali misti, pneumatici usati"],["Spazi","retro del capannone, in parte coperto"],["Ritiri","a chiamata, senza calendario"]],[
  ("Attribuisci a ciascun rifiuto il codice EER e indica se è pericoloso.",10,"Oli minerali per motori non clorurati 13 02 05*, pericoloso. Filtri dell’olio 16 01 07*, pericoloso. Stracci contaminati da sostanze pericolose 15 02 02*, pericoloso (se non contaminati 15 02 03). Batterie al piombo 16 06 01*, pericoloso. Imballaggi in materiali misti 15 01 06, non pericoloso. Pneumatici fuori uso 16 01 03, non pericoloso.",["Ho usato i codici a sei cifre con l’asterisco per i pericolosi","Ho riconosciuto che gli stracci possono essere voce a specchio","Ho distinto i quattro rifiuti pericolosi dai due non pericolosi"],"Es.: oli esausti → 13 02 05*, pericoloso; …"),
  ("Organizza il deposito temporaneo: dove, come e con quale criterio di avvio.",8,"Area coperta e pavimentata, con bacini di contenimento per oli e filtri; contenitori separati per categorie omogenee, etichettati con codice EER e caratteristiche di pericolo; batterie in contenitori a tenuta resistenti agli acidi. Criterio dichiarato: avvio almeno trimestrale indipendentemente dalle quantità, oppure al raggiungimento di 30 m³ di cui al massimo 10 di pericolosi, e comunque entro un anno.",["Ho previsto copertura e bacini di contenimento","Ho previsto separazione ed etichettatura","Ho scelto e scritto un criterio di avvio"]),
  ("Elenca gli adempimenti di tracciabilità a cui l’officina è tenuta.",8,"Iscrizione al RENTRI dell’unità locale, perché produce rifiuti pericolosi; registro cronologico di carico e scarico digitale, con annotazioni entro dieci giorni lavorativi e trasmissione mensile dei dati; formulario digitale per i ritiri, emesso tramite il RENTRI; verifica dell’iscrizione all’Albo del trasportatore e dell’autorizzazione dell’impianto; controllo della conferma di accettazione entro tre mesi.",["Ho indicato l’iscrizione al RENTRI","Ho indicato registro e formulario digitali con i termini","Ho previsto le verifiche su trasportatore e impianto"])],
 "Ecco un laboratorio completo. Un’officina con sei dipendenti produce oli, filtri, stracci, batterie, imballaggi e pneumatici. In tre compiti attribuisci i codici, organizzi il deposito temporaneo ed elenchi gli adempimenti di tracciabilità. Per ogni compito scrivi la tua soluzione, poi confrontala con quella di riferimento e valuta che cosa hai considerato.","Decisione 2014/955/UE · artt. 184, 185-bis, 188-bis, 190 D.lgs. 152/2006")])
E(C,'M1-Z4','Il formulario digitale: emissione, vidimazione e firme',[ES("Esempio guidato · Il ritiro con formulario digitale","Dalla richiesta di ritiro alla conferma dell’impianto.",[
 ["Emissione","Il produttore emette il formulario con il gestionale interoperabile o con i servizi del portale RENTRI.","Gestionale o portale"],
 ["Vidimazione","Il RENTRI vidima il formulario assegnando un numero identificativo univoco.","Numero univoco"],
 ["Partenza","Produttore e trasportatore firmano digitalmente; quantità e caratteristiche sono quelle del rifiuto caricato.","Firme alla partenza"],
 ["Arrivo","L’impianto registra la quantità accettata e firma: in caso di respingimento lo indica.","Accettazione o respingimento"],
 ["Chiusura","I dati sono trasmessi al RENTRI; il produttore verifica l’accettazione e annota lo scarico nel registro.","Verifica e annotazione"]],
 "Seguiamo un ritiro con il formulario digitale. Il produttore lo emette con il proprio gestionale o con il portale. Il RENTRI lo vidima con un numero univoco. Alla partenza firmano produttore e trasportatore. All’arrivo l’impianto indica la quantità accettata e firma. I dati confluiscono nel RENTRI, e il produttore verifica l’accettazione e annota lo scarico nel registro.","Art. 7 D.M. 59/2023")])
E(C,'M1-Z5','Indisponibilità dei servizi: le modalità operative di sicurezza',[SC("Il portale non risponde","Venerdì alle 16 il trasportatore è nel piazzale per un ritiro di rifiuti pericolosi. Il gestionale non riesce a ottenere la vidimazione del formulario.",[
 ("Che cosa verifichi per primo?",[["Se l’indisponibilità è effettiva e comunicata dai canali ufficiali del RENTRI, distinguendo un guasto del servizio da un problema del tuo gestionale",True,"Corretto: le modalità di sicurezza valgono solo per l’indisponibilità accertata dei servizi."],["Niente: rimandi il ritiro di un mese",False,"Il rinvio può far superare i limiti del deposito temporaneo."],["Fai partire il trasporto senza formulario",False,"Il trasporto senza formulario è sanzionato per produttore e trasportatore."]]),
 ("L’indisponibilità è confermata. Come procedi?",[["Applichi la procedura del D.D. 5 febbraio 2026, n. 25, con le indicazioni richieste",True,"Corretto: la procedura consente di proseguire l’attività senza interruzioni."],["Usi un vecchio formulario cartaceo già compilato",False,"Va seguita la procedura prevista."],["Trasmetti i dati via e-mail all’ARPA",False,"Non è la procedura prevista."]]),
 ("Al ripristino del servizio che cosa fai?",[["Nulla",False,"Annotazioni e trasmissioni vanno regolarizzate."],["Regolarizzi annotazioni e trasmissioni nei termini indicati e conservi le prove dell’indisponibilità",True,"Corretto: conservare le evidenze tutela l’impresa in caso di controllo."],["Annulli il ritiro",False,"Il ritiro è avvenuto regolarmente con la procedura di sicurezza."]])],
 "Accertare l’indisponibilità, applicare la procedura di sicurezza, regolarizzare al ripristino e conservare le prove: l’attività non si ferma e la tracciabilità resta completa.","Il RENTRI non risponde durante un ritiro. Decidi come procedere.","D.D. 5 febbraio 2026, n. 25 · D.D. 30 ottobre 2025, n. 319")])
E(C,'M1-Z6','Annotazioni, trasmissioni e conservazione: i termini',[LB("Laboratorio · Un mese di registro","Ti occupi del registro digitale di una carrozzeria che gestisce in proprio gli adempimenti, senza delegato.",[
  ["3 marzo","prodotti 120 kg di vernici di scarto (08 01 11*)"],["10 marzo","prodotti 40 kg di filtri della cabina di verniciatura"],["24 marzo","ritiro di 160 kg con formulario digitale"],["Aprile","nessuna produzione e nessun ritiro"],["Delegato","nessuno"]],[
  ("Indica entro quando vanno annotati i tre movimenti di marzo.",6,"Ogni carico va annotato almeno entro dieci giorni lavorativi dalla produzione: quello del 3 marzo entro il 17 marzo circa, quello del 10 marzo entro il 24 marzo circa, considerando i giorni lavorativi. Lo scarico del 24 marzo va annotato entro dieci giorni lavorativi dallo scarico.",["Ho applicato i dieci giorni lavorativi","Ho annotato separatamente carichi e scarico","Ho collegato lo scarico al formulario"]),
  ("Entro quando trasmetti i dati di marzo al RENTRI? E per aprile?",5,"I dati di marzo si trasmettono entro la fine del mese successivo, cioè entro il 30 aprile. Per aprile, senza annotazioni, non c’è nulla da trasmettere. Se la carrozzeria si affidasse a un delegato, il termine sarebbe la fine del secondo mese successivo.",["Ho indicato il 30 aprile","Ho considerato il mese senza annotazioni","Ho distinto il caso del delegato"]),
  ("Che cosa controlli dopo il ritiro del 24 marzo?",5,"Che l’impianto abbia confermato l’accettazione e la quantità, verificando eventuali differenze o respingimenti; che il trasportatore fosse iscritto all’Albo nella categoria corretta; e che il registro sia conservato per tre anni dall’ultima registrazione.",["Ho previsto il controllo dell’accettazione","Ho previsto la verifica del trasportatore","Ho indicato la conservazione triennale"])],
 "Questo laboratorio simula un mese di registro digitale. Il dossier riporta le produzioni e il ritiro di marzo e un aprile senza movimenti. Stabilisci i termini di annotazione e di trasmissione e i controlli dopo il ritiro, poi confronta ogni risposta con la soluzione di riferimento.","Art. 190 D.lgs. 152/2006 · D.M. 59/2023")])
E(C,'M1-Z7','Le categorie dell’Albo gestori ambientali',[LB("Laboratorio · Verificare la filiera prima del ritiro","Devi affidare a nuovi fornitori il ritiro di oli esausti e di imballaggi misti.",[
  ["Rifiuti","oli esausti 13 02 05*, 1.200 kg l’anno; imballaggi misti 15 01 06, 8 t l’anno"],["Trasportatore proposto","iscritto all’Albo in categoria 4"],["Impianto proposto per gli oli","autorizzato alle operazioni R13 e R9"],["Impianto per gli imballaggi","autorizzato all’operazione R13"]],[
  ("Il trasportatore può ritirare entrambi i rifiuti? Motiva.",7,"No. La categoria 4 riguarda la raccolta e il trasporto di rifiuti speciali non pericolosi prodotti da terzi: va bene per gli imballaggi misti. Per gli oli esausti, pericolosi, serve l’iscrizione in categoria 5. Va controllato anche che i codici EER e i mezzi siano compresi nel provvedimento di iscrizione.",["Ho distinto categoria 4 e categoria 5","Ho previsto il controllo dei codici EER nel provvedimento","Ho previsto il controllo dei mezzi"]),
  ("Le autorizzazioni degli impianti sono adeguate?",7,"Sì, se i codici EER sono compresi nelle autorizzazioni. R9 è la rigenerazione degli oli, R13 la messa in riserva: con R13 il rifiuto andrà poi a un ulteriore impianto di recupero. Per le operazioni intermedie la responsabilità del produttore segue le regole dell’art. 188.",["Ho verificato la presenza dei codici EER nell’autorizzazione","Ho spiegato R9 e R13","Ho considerato le operazioni intermedie"]),
  ("Quali documenti chiedi e conservi prima di firmare il contratto?",6,"Provvedimento di iscrizione all’Albo del trasportatore con categorie, codici EER e targhe; autorizzazione dell’impianto con le operazioni e i codici; verifica della validità alla data del ritiro; contratto che richiami gli obblighi di tracciabilità. Le verifiche vanno ripetute periodicamente.",["Ho elencato iscrizione all’Albo e autorizzazione","Ho previsto la verifica delle scadenze","Ho previsto controlli periodici"])],
 "In questo laboratorio verifichi una filiera di gestione prima di affidare i rifiuti. Il dossier indica i rifiuti, il trasportatore e gli impianti proposti. Valuta l’iscrizione all’Albo, le autorizzazioni degli impianti e i documenti da conservare, poi confronta le tue risposte con la soluzione di riferimento.","Artt. 188 e 212 D.lgs. 152/2006 · Allegato C alla Parte IV")])
E(C,'M1-Z8','Il quadro sanzionatorio',[CL("Sanzione amministrativa o rilievo penale?","Seleziona una violazione, poi la conseguenza.",["Sanzione amministrativa (art. 258)","Rilievo penale"],[
 ["Omessa iscrizione al RENTRI",0,"È sanzionata in via amministrativa dall’art. 258."],
 ["Registro tenuto in modo incompleto",0,"Sanzione amministrativa."],
 ["Formulario con indicazioni incomplete o inesatte",0,"Sanzione amministrativa."],
 ["Formulario con dati falsi sulla natura del rifiuto",1,"Rinvio all’art. 483 c.p.: falsità ideologica."],
 ["Mancata trasmissione al RENTRI dei dati dei formulari dopo il 15 settembre 2026",0,"Comma 10-bis: sanzione amministrativa."],
 ["Spedizione di rifiuti con certificato di analisi falso",1,"L’uso di un certificato falso ha rilievo penale."]],
 "Sei violazioni della tracciabilità. Distingui quelle punite con sanzione amministrativa da quelle con rilievo penale.","Art. 258 D.lgs. 152/2006"),
 AP("La tracciabilità nella tua azienda","Verifica come la tua organizzazione gestisce la tracciabilità.",["Unità locali iscritte al RENTRI","Registro digitale aggiornato","Formulario digitale in uso","Delega formalizzata a un consulente o a un’associazione","Verifica periodica di trasportatori e impianti","Controllo delle conferme di accettazione","Procedura per l’indisponibilità del portale"],"Il punto che miglioreresti per primo e come","Es.: nessun controllo delle accettazioni → scadenzario mensile dei formulari aperti",
  "Verifica come la tua azienda gestisce la tracciabilità dei rifiuti e indica il primo punto da migliorare.",3)])
E(C,'M1-Z9','Voci assolute e voci a specchio',[LB("Laboratorio · Le terre di scavo del cantiere","Un’impresa edile rimuove terreno da un’area ex industriale dove in passato c’era un deposito di carburanti.",[
  ["Rifiuto","terra e rocce da scavo, circa 300 t"],["Storia del sito","ex deposito di carburanti, dismesso da 15 anni"],["Codici possibili","17 05 03* terra e rocce contenenti sostanze pericolose / 17 05 04 terra e rocce diverse da quelle della voce 17 05 03"],["Analisi disponibili","nessuna"]],[
  ("Che tipo di voce è e come procedi per scegliere il codice?",6,"È una coppia di voci a specchio: il codice dipende dal contenuto di sostanze pericolose. Si ricostruisce la storia del sito e del processo, si individuano le sostanze pertinenti, come gli idrocarburi, e si campiona in modo rappresentativo, secondo le Linee guida SNPA sulla classificazione dei rifiuti.",["Ho riconosciuto la voce a specchio","Ho usato la storia del sito per individuare le sostanze","Ho previsto un campionamento rappresentativo"]),
  ("Le analisi trovano idrocarburi. Come stabilisci se il rifiuto è pericoloso?",7,"Si confrontano le concentrazioni delle sostanze con le soglie delle caratteristiche di pericolo HP dell’allegato III della direttiva 2008/98/CE, come modificato dal regolamento (UE) 1357/2014 e dal regolamento (UE) 2017/997 per HP14. Se anche una sola caratteristica è soddisfatta, il codice è 17 05 03*.",["Ho citato le caratteristiche HP","Ho indicato che basta una caratteristica","Ho collegato l’esito al codice con asterisco"]),
  ("Quali conseguenze ha la classificazione sugli adempimenti?",5,"Se pericoloso: iscrizione al RENTRI come produttore di rifiuti pericolosi, registro e formulario digitali, trasportatore in categoria 5 e impianto autorizzato per quel codice. Se non pericoloso, restano formulario e verifiche della filiera. In entrambi i casi il rapporto di prova e la motivazione si conservano.",["Ho distinto le conseguenze nei due casi","Ho indicato la categoria 5 dell’Albo","Ho previsto la conservazione delle analisi"])],
 "Nel laboratorio classifichi le terre di scavo di un’area ex industriale. È un caso tipico di voce a specchio. Stabilisci come scegliere il codice, come valutare la pericolosità dopo le analisi e quali adempimenti ne derivano, poi confronta le tue risposte con la soluzione di riferimento.","Decisione 2014/955/UE · Reg. (UE) 1357/2014 · Linee guida SNPA")])
